"""Helpers for JSONL log summaries."""

import json


def normalize_level(value):
    """Normalize a level for stable counting."""
    return str(value).strip().lower()


def iter_jsonl(lines):
    """Yield decoded JSON objects, ignoring blank lines."""
    for line in lines:
        if line.strip():
            yield json.loads(line)


def summarize_jsonl(lines):
    """Return key-sorted severity counts."""
    counts = {}
    for item in iter_jsonl(lines):
        level = normalize_level(item.get("level", "unknown"))
        counts[level] = counts.get(level, 0) + 1
    return dict(sorted(counts.items()))

